export function storyDialogueComplete(d,a){return !!d&&!!a&&d.choices.some(c=>c.id===a.choiceId)&&(a.cursor===d.lines.length||legacyEnds[d.id]?.includes(a.cursor)===true);}
export function storyKnowledgeMatches(actual,expected){return Array.isArray(actual)&&actual.length===expected.length&&actual.every((row,i)=>{const target=expected[i];if(!row||typeof row!=='object'||Array.isArray(row))return false;const textOK=row.text===target.text||legacyKnowledge[target.sourceScene+'/'+target.id]?.includes(row.text)===true;return textOK&&JSON.stringify({...row,text:target.text})===JSON.stringify(target);});}
